"    // 8. Fetch Additional Charges
    try {
      const chargesRes = await posService.getAdditionalCharges(outletIdToPass);
      setAvailableCharges((chargesRes.data || []).filter(c => c.is_active));
      localStorage.setItem('pos_additional_charges', JSON.stringify(chargesRes.data || []));
    } catch (e) {
      console.warn("initApp - Failed to fetch additional charges:", e);
    }

    // 8b. Fetch Staff/Waiters
    try {
      const staffRes = await posService.getStaff();
      const staffList = staffRes.data || [];
      const waitersOnly = staffList.filter(s => {
        const des = String(s.designation_name || '').toLowerCase();
        const role = String(s.role || '').toLowerCase();
        return des.includes('waiter') || des.includes('captain') || des.includes('server') || des.includes('staff') || role.includes('staff') || role.includes('waiter');
      });
      const finalWaiters = waitersOnly.length > 0 ? waitersOnly : staffList;
      setWaitersList(finalWaiters);
      localStorage.setItem('pos_waiters', JSON.stringify(finalWaiters));
    } catch (e) {
      console.warn("initApp - Failed to fetch staff/waiters:", e);
    }"

